/* P7.24: Navigation is OUT OF FLOW. The original P7.22 flex row and its
   buttons receive no padding, margin, width or min-height changes. */
.xen-forge-action-rack{position:relative;}
.xen-forge-action-rack>.xen-forge-up-triangle{
 position:absolute;right:0;bottom:0;z-index:2;width:80px;height:80px;
 margin:0;padding:0;box-sizing:border-box;border:0;border-radius:0;
 background:#2ab8c4;color:#e0fdff;cursor:pointer;user-select:none;
 clip-path:polygon(100% 0,100% 100%,0 100%);font-family:inherit;font-size:12px;font-weight:750;
}
.xen-forge-up-triangle::before{content:"";position:absolute;inset:1.5px;
 background:#103842;clip-path:polygon(100% 0,100% 100%,0 100%);pointer-events:none;}
.xen-forge-action-rack>.xen-forge-up-triangle:is(:hover,:focus-visible){background:#8eecf1;}
.xen-forge-action-rack>.xen-forge-up-triangle:is(:hover,:focus-visible)::before{background:#225765;}
.xen-forge-action-rack>.xen-forge-up-triangle:focus-visible{outline:2px solid #a5f3fc;outline-offset:2px;}
.xen-forge-up-chevron,.xen-forge-up-label{position:absolute;z-index:1;display:block;pointer-events:none;
 color:#dffbff;text-shadow:0 1px 2px #04161c;text-align:center;}
/* Arrow ABOVE UP, unlike the reverted P7.23 variant. Both inside the triangle. */
.xen-forge-up-chevron{right:12px;bottom:25px;width:22px;font-size:25px;line-height:25px;font-weight:700;}
.xen-forge-up-label{right:10px;bottom:7px;width:26px;font-size:12px;line-height:16px;letter-spacing:.035em;}
/* At very narrow widths the action row has no guaranteed 80px spare space.
   Hide the purely convenient scroll shortcut rather than cover musical actions. */
@media(max-width:1099px){.xen-forge-action-rack>.xen-forge-up-triangle{display:none;}}

